import SwiftUI
import WidgetKit

struct RandomVerseEntry: TimelineEntry {
    let date: Date
    let book: String
    let chapter: Int
    let verse: Int
    let text: String
}

/// Shows one verse per day from a small curated list bundled with the widget
/// (`LockScreenVerses.json`, generated by `Scripts/make_lockscreen_verses.py`).
/// Widgets have a tight memory limit, so the full Bible is never loaded here.
struct RandomVerseProvider: TimelineProvider {
    typealias Entry = RandomVerseEntry

    /// Days of entries handed to WidgetKit per refresh; each switches at local midnight.
    private static let daysPerTimeline = 7

    func placeholder(in context: Context) -> Entry {
        RandomVerseEntry(date: Date(), book: "John", chapter: 3, verse: 16, text: "For God so loved the world…")
    }

    func getSnapshot(in context: Context, completion: @escaping (Entry) -> Void) {
        completion(entry(for: Date()) ?? placeholder(in: context))
    }

    func getTimeline(in context: Context, completion: @escaping (Timeline<Entry>) -> Void) {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        let days = (0..<Self.daysPerTimeline).compactMap {
            calendar.date(byAdding: .day, value: $0, to: today)
        }

        // Today's entry starts now; later entries start at each midnight.
        var entries = days.compactMap(entry(for:))
        if !entries.isEmpty {
            entries[0] = RandomVerseEntry(
                date: Date(),
                book: entries[0].book,
                chapter: entries[0].chapter,
                verse: entries[0].verse,
                text: entries[0].text
            )
        }
        completion(Timeline(entries: entries.isEmpty ? [placeholder(in: context)] : entries, policy: .atEnd))
    }

    // MARK: - Daily verse

    /// The verse for the local day containing `date`. The list is stored pre-shuffled,
    /// so consecutive days show unrelated verses and the cycle repeats yearly.
    private func entry(for date: Date) -> RandomVerseEntry? {
        let verses = LockScreenVerseList.verses
        guard !verses.isEmpty else { return nil }

        let calendar = Calendar.current
        // Count local midnights since a fixed date. `ordinality(of: .day, in: .era)` counts
        // in UTC, which would change the verse in the evening instead of at midnight.
        let reference = calendar.date(from: DateComponents(year: 2001, month: 1, day: 1)) ?? .distantPast
        let dayIndex = calendar.dateComponents(
            [.day],
            from: calendar.startOfDay(for: reference),
            to: calendar.startOfDay(for: date)
        ).day ?? 0
        let verse = verses[abs(dayIndex) % verses.count]
        return RandomVerseEntry(
            date: calendar.startOfDay(for: date),
            book: verse.book,
            chapter: verse.chapter,
            verse: verse.verse,
            text: verse.text
        )
    }
}

/// The curated lock-screen verses, decoded once per widget process (about 66 KB).
private enum LockScreenVerseList {
    struct Verse: Decodable {
        let book: String
        let chapter: Int
        let verse: Int
        let text: String
    }

    static let verses: [Verse] = {
        guard let url = Bundle.main.url(forResource: "LockScreenVerses", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let verses = try? JSONDecoder().decode([Verse].self, from: data) else {
            return []
        }
        return verses
    }()
}

struct RandomVerseLockScreenView: View {
    @Environment(\.widgetFamily) private var family
    let entry: RandomVerseEntry

    // Build the content once, then apply background adoption in body.
    @ViewBuilder
    private var content: some View {
        switch family {
        case .accessoryInline:
            // Single-line: Book N:M – text
            Text(inlineText)
                .font(.caption2)
                .widgetURL(deepLinkURL())
        case .accessoryCircular:
            ZStack {
                // Keep it simple: reference in the circle
                VStack(spacing: 0) {
                    Text(shortBookAbbrev(entry.book))
                        .font(.caption2.weight(.semibold))
                        .lineLimit(1)
                    Text("\(entry.chapter):\(entry.verse)")
                        .font(.caption.weight(.bold))
                        .lineLimit(1)
                }
            }
            .widgetURL(deepLinkURL())
        case .accessoryRectangular:
            // Exactly 3 lines:
            // 1) Reference (bold, single line)
            // 2-3) Scripture text (regular, up to 2 lines)
            VStack(alignment: .leading, spacing: 1.5) {
                Text("\(entry.book) \(entry.chapter):\(entry.verse)")
                    .font(.caption2.weight(.semibold))
                    .lineLimit(1)

                Text(entry.text)
                    .font(.footnote) // bigger than caption
                    .lineLimit(2) // lines 2 and 3
                    .truncationMode(.tail)
            }
            .widgetURL(deepLinkURL())
        default:
            // Fallback for any future families
            VStack(alignment: .leading, spacing: 4) {
                Text("\(entry.book) \(entry.chapter):\(entry.verse)")
                    .font(.caption2.weight(.semibold))
                Text(entry.text)
                    .font(.caption2)
                    .lineLimit(3)
            }
            .widgetURL(deepLinkURL())
        }
    }

    var body: some View {
        // Adopt the iOS 17+ background API to remove the system overlay on devices.
        if #available(iOSApplicationExtension 17.0, *) {
            if family == .accessoryCircular || family == .accessoryRectangular {
                // Opt into the system’s tinted background for accessory widgets.
                content
                    .containerBackground(.fill.tertiary, for: .widget)
            } else {
                // Keep inline (and other) appearance unchanged while adopting the API.
                content
                    .containerBackground(for: .widget) { Color.clear }
            }
        } else {
            content
        }
    }

    private var inlineText: String {
        guard !entry.book.isEmpty, entry.chapter > 0, entry.verse > 0 else { return "Bible verse" }
        let ref = "\(entry.book) \(entry.chapter):\(entry.verse)"
        let snippet = entry.text
        return "\(ref) — \(snippet)"
    }

    private func shortBookAbbrev(_ name: String) -> String {
        // Very compact abbreviation for circular
        let parts = name.split(separator: " ")
        if parts.count == 1 {
            return String(parts[0].prefix(3)).uppercased()
        }
        // Preserve leading number for numbered books
        if let first = parts.first, first.allSatisfy({ $0.isNumber }) {
            let rest = parts.dropFirst().first.map { String($0.prefix(3)).uppercased() } ?? ""
            return "\(first) \(rest)"
        }
        return String(parts.first!.prefix(3)).uppercased()
    }

    private func deepLinkURL() -> URL? {
        guard !entry.book.isEmpty, entry.chapter > 0, entry.verse > 0 else { return nil }
        var comps = URLComponents()
        comps.scheme = "thebible"
        comps.host = "open"
        comps.queryItems = [
            URLQueryItem(name: "book", value: entry.book),
            URLQueryItem(name: "chapter", value: "\(entry.chapter)"),
            URLQueryItem(name: "verse", value: "\(entry.verse)")
        ]
        return comps.url
    }
}

struct RandomVerseLockScreenWidget: Widget {
    let kind = "RandomVerseLockScreenWidget"

    var body: some WidgetConfiguration {
        StaticConfiguration(kind: kind, provider: RandomVerseProvider()) { entry in
            RandomVerseLockScreenView(entry: entry)
        }
        .configurationDisplayName("Random Verse")
        .description("Shows a random Bible verse on your Lock Screen.")
        .supportedFamilies([
            .accessoryInline,
            .accessoryCircular,
            .accessoryRectangular
        ])
    }
}

#Preview(as: .accessoryRectangular) {
    RandomVerseLockScreenWidget()
} timelineProvider: {
    RandomVerseProvider()
}
